from google.cloud import pubsub_v1
import os
import json

class DeadLetterPublisher:
    def __init__(self):
        self.project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
        self.dead_letter_topic = os.getenv("PUBSUB_DEAD_LETTER_TOPIC", "dead-letter-topic")
        self.publisher = pubsub_v1.PublisherClient()
        self.topic_path = self.publisher.topic_path(self.project_id, self.dead_letter_topic)

    def send_to_dead_letter(self, original_topic, message_data, attributes=None, error_details=None):
        if attributes is None:
            attributes = {}
        if error_details:
            attributes["error_details"] = json.dumps(error_details)
        attributes["original_topic"] = original_topic

        future = self.publisher.publish(
            self.topic_path,
            data=message_data.encode("utf-8"),
            **attributes
        )
        return future.result()
